import pandas as pd
import numpy as np
import itertools

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Determine the maximum number of positions across all tuples
    max_len = 0
    for item in data_list:
        if isinstance(item, tuple) and len(item) > max_len:
            max_len = len(item)

    # Initialize lists to hold values for each position
    position_values = [[] for _ in range(max_len)]

    for item in data_list:
        if isinstance(item, tuple):
            for i, value in enumerate(item):
                # Check if value is numeric (int or float, not bool, not string, not list, etc.)
                if isinstance(value, (int, float)) and not isinstance(value, bool):
                    position_values[i].append(value)

    # Calculate mean for each position
    means = []
    for values in position_values:
        if len(values) > 0:
            means.append(np.mean(values))
        else:
            means.append(np.nan)

    # Create DataFrame
    index = [f'Position {i}' for i in range(max_len)]
    df = pd.DataFrame({'Mean Value': means}, index=index)

    return df

