import pandas as pd
import os
import glob

def task_func(my_list, file_dir='./data_files/', file_ext='.csv'):
    if not isinstance(my_list, list):
        raise TypeError("my_list must be a list")

    # Add the element '12' to the list
    my_list.append('12')

    # Calculate the sum of numbers in the list
    total = 0
    for item in my_list:
        if isinstance(item, (int, float)):
            total += item
        elif isinstance(item, str):
            try:
                total += int(item)
            except ValueError:
                try:
                    total += float(item)
                except ValueError:
                    pass

    # Get all CSV files in the directory
    pattern = os.path.join(file_dir, f'*{file_ext}')
    files = sorted(glob.glob(pattern))

    if not files:
        raise FileNotFoundError(f"No files found in the specified directory: {file_dir}")

    # Take the first 'total' number of files
    num_files = int(total) if isinstance(total, float) else total
    if num_files <= 0:
        # If no files to concatenate, return an empty DataFrame
        return pd.DataFrame()

    # Concatenate the selected CSV files into a single DataFrame
    dfs = []
    for i, file in enumerate(files):
        if i >= num_files:
            break
        dfs.append(pd.read_csv(file))

    if not dfs:
        return pd.DataFrame()

    result = pd.concat(dfs, ignore_index=True)
    return result

